import type { Cents } from "../money";

export interface Line {
  sku: string;
  qty: number;
  unitPrice: Cents;
}

export function subtotal(lines: Line[]): Cents {
  return lines.reduce((sum, l) => sum + l.unitPrice * l.qty, 0) as Cents;
}

export function totalWithVat(lines: Line[], vatRate: number): Cents {
  const euros = subtotal(lines) / 100;
  const gross = euros * (1 + vatRate);
  return (gross * 100) as Cents;
}
